-- Execute no SQL Editor do Supabase. Cada registro pertence ao usuário autenticado.
create extension if not exists pgcrypto;
create table if not exists public.products (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id),barcode text,name text not null,category text,unit text default 'UN',cost numeric(14,2) default 0,price numeric(14,2) default 0,stock numeric(14,3) default 0,created_at timestamptz default now());
create table if not exists public.suppliers (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),name text not null,cnpj text,phone text,email text,notes text,created_at timestamptz default now());
create table if not exists public.invoices (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),number text not null,series text,issue_date date,supplier_id uuid references public.suppliers(id) on delete set null,supplier_name text,total numeric(14,2),access_key text,created_at timestamptz default now());
create table if not exists public.invoice_items (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),invoice_id uuid not null references public.invoices(id) on delete cascade,product_id uuid references public.products(id) on delete set null,code text,description text,quantity numeric(14,3),unit text,unit_cost numeric(14,4),total numeric(14,2),created_at timestamptz default now());
create table if not exists public.tasks (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),title text not null,description text,priority text default 'Média',status text default 'Pendente',due_date date,created_at timestamptz default now());
create table if not exists public.events (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),title text not null,description text,starts_at timestamptz,location text,created_at timestamptz default now());
create table if not exists public.price_history (id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id),product_id uuid references public.products(id) on delete set null,old_cost numeric(14,4),new_cost numeric(14,4),source text,created_at timestamptz default now());
do $$ declare t text; begin foreach t in array array['products','suppliers','invoices','invoice_items','tasks','events','price_history'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists owner_select on public.%I',t);execute format('drop policy if exists owner_insert on public.%I',t);execute format('drop policy if exists owner_update on public.%I',t);execute format('drop policy if exists owner_delete on public.%I',t);execute format('create policy owner_select on public.%I for select to authenticated using (user_id=auth.uid())',t);execute format('create policy owner_insert on public.%I for insert to authenticated with check (user_id=auth.uid())',t);execute format('create policy owner_update on public.%I for update to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid())',t);execute format('create policy owner_delete on public.%I for delete to authenticated using (user_id=auth.uid())',t);end loop;end $$;
create index if not exists products_owner_idx on public.products(user_id);
create index if not exists invoices_owner_idx on public.invoices(user_id);
create index if not exists tasks_owner_idx on public.tasks(user_id);
